insert into public.bf_questions (id, pack, is_free, category, difficulty, prompt, choices, answer, quip)
values
  ('cc-001', 'starter', true, 'claude-code', 1, 'Which file does Claude Code read for project instructions?', '["README.ai","CLAUDE.md",".clauderc","PLEASE_READ_ME.txt"]'::jsonb, 1, 'Claude reads CLAUDE.md every session. Your teammates read it never.'),
  ('cc-002', 'starter', true, 'claude-code', 1, 'What does /compact do?', '["Minifies your source code","Shrinks your terminal font","Summarizes the conversation to free up context","Squashes all your git commits"]'::jsonb, 2, 'Less context, same vibes.'),
  ('cc-003', 'starter', true, 'claude-code', 1, 'Which key interrupts Claude mid-task?', '["F5","Esc","Ctrl+Alt+Del","Yelling \"STOP\" at the monitor"]'::jsonb, 1, 'Esc works. Yelling is optional but therapeutic.'),
  ('cc-004', 'starter', true, 'claude-code', 2, 'What does `claude -p "fix the tests"` do?', '["Opens pair-programming mode with a parrot","Runs the prompt non-interactively and prints the result","Turns on polite mode","Publishes your repo to npm"]'::jsonb, 1, 'Print mode: perfect for scripts, CI and other places where nobody is watching.'),
  ('cc-005', 'starter', true, 'claude-code', 1, 'What does /clear do?', '["Deletes your repo (finally)","Starts a fresh conversation without the old context","Clears your browser cache","Clears your conscience"]'::jsonb, 1, 'A clean slate. Your bugs are still there, though.'),
  ('cc-006', 'starter', true, 'claude-code', 2, 'Which flag picks up an earlier conversation?', '["--again","--rewind-time","--resume","--undo-my-life"]'::jsonb, 2, '--resume brings back the conversation. Your weekend stays gone.'),
  ('cc-007', 'starter', true, 'claude-code', 2, 'Which hook event fires before a tool runs?', '["PostToolUse","BeforeCoffee","PreToolUse","OnToolMaybe"]'::jsonb, 2, 'PreToolUse can block a call before it runs. PostToolUse reacts after.'),
  ('cc-008', 'starter', true, 'claude-code', 1, 'What is plan mode for?', '["Planning your vacation","Researching and proposing a plan before editing anything","Replying only in Gantt charts","Booking meetings nobody wanted"]'::jsonb, 1, 'Measure twice, `git commit` once.'),
  ('cc-009', 'starter', true, 'claude-code', 2, 'Where do shared project settings such as permissions live?', '["~/.bashrc",".claude/settings.json","/etc/hosts","A sticky note on the monitor"]'::jsonb, 1, 'Commit .claude/settings.json and your whole team gets the same rules.'),
  ('cc-010', 'starter', true, 'claude-code', 1, 'Which command scans your codebase and writes a starter CLAUDE.md?', '["/bootstrap","/readme","/init","/please"]'::jsonb, 2, '/init. Manners are still appreciated.'),
  ('cc-011', 'starter', true, 'claude-code', 2, 'Why hand a side task to a subagent?', '["Claude gets lonely","It runs in its own context window, which keeps the main thread lean","It doubles your bill for fun","Subagents can run tests in production"]'::jsonb, 1, 'Delegation: not just for managers anymore.'),
  ('cc-012', 'starter', true, 'claude-code', 1, 'What does /cost show?', '["Your cloud bill for the year","What the current session has spent","Your hourly consulting rate","The price of the pizza you deserve"]'::jsonb, 1, 'Knowledge is power. Sometimes it is also pain.'),
  ('cc-013', 'starter', true, 'claude-code', 1, 'How do you install a plugin like BugFlix in Claude Code?', '["npm i -g vibes","/plugin install","sudo make me-a-sandwich","apt-get install fun"]'::jsonb, 1, 'Which is exactly how you got here. Hi!'),
  ('cc-014', 'starter', true, 'claude-code', 2, 'What does Shift+Tab do at the Claude Code prompt?', '["Un-tabs your life","Cycles permission modes, such as auto-accept edits and plan mode","Switches to spaces","Opens a new browser tab"]'::jsonb, 1, 'Tabs vs spaces remains unresolved.'),
  ('cc-015', 'starter', true, 'claude-code', 2, 'Which settings hook event fires when Claude finishes responding?', '["Done","Stop","Finally","MicDrop"]'::jsonb, 1, 'Stop hooks: great for "run the linter before you say you are done".'),
  ('cc-016', 'starter', true, 'claude-code', 2, 'When is `--dangerously-skip-permissions` reasonable?', '["On your production laptop, always","In an isolated sandbox or container","When you feel lucky","Every Friday at 4:59 pm"]'::jsonb, 1, 'The flag is literally called "dangerously". Read the room.'),
  ('cc-017', 'starter', true, 'claude-code', 2, 'What does starting a prompt with `!` do in Claude Code?', '["Makes Claude answer louder","Runs it as a shell command (bash mode)","Marks the prompt as urgent","Negates everything Claude says"]'::jsonb, 1, 'Bash mode: run a command without leaving the chat.'),
  ('cc-018', 'starter', true, 'claude-code', 1, 'Typing `@` followed by a path in the prompt…', '["Tweets the file","Mentions the file so its contents come along","Emails your manager","Assigns the file a username"]'::jsonb, 1, '@-mentions for files: less copy-paste, more flow.'),
  ('cc-019', 'starter', true, 'claude-code', 3, 'A hook in a plugin can do which of these?', '["Block or rewrite a tool call before it runs","Change the model weights","Make Claude skip its tests silently","Mine crypto in your terminal"]'::jsonb, 0, 'Hooks guard and shape tool calls. Weights stay where they are.'),
  ('cc-020', 'starter', true, 'claude-code', 2, 'Your Claude Code session is getting long and sluggish. Best first move?', '["Buy a bigger monitor","/compact or /clear","Restart the laptop","Type faster"]'::jsonb, 1, 'Context is a budget. Spend it on code, not ancient history.'),
  ('api-001', 'starter', true, 'llm-apis', 1, 'HTTP 429 means…', '["The model is tired","Too Many Requests: slow down","Created successfully","Payment required"]'::jsonb, 1, '429: the API equivalent of "new phone, who dis".'),
  ('api-002', 'starter', true, 'llm-apis', 2, 'Which parameter is required in Anthropic''s Messages API to cap the reply length?', '["max_vibes","length_limit","max_tokens","stop_after"]'::jsonb, 2, 'max_tokens is required. max_vibes is in beta forever.'),
  ('api-003', 'starter', true, 'llm-apis', 2, 'Which header carries your key for Anthropic''s API?', '["x-api-key","X-Please","Cookie: hunter2","X-Trust-Me"]'::jsonb, 0, 'And it never goes in a public repo. Never.'),
  ('api-004', 'starter', true, 'llm-apis', 2, 'A response with stop_reason "tool_use" means…', '["The model crashed","The model wants you to run a tool and send back the result","The tool was deprecated","The model wants a hammer"]'::jsonb, 1, 'Run the tool, return a tool_result, and the loop goes on.'),
  ('api-005', 'starter', true, 'llm-apis', 2, 'Streaming LLM responses usually arrive as…', '["Fax","Server-sent events","Carrier pigeon","FTP uploads"]'::jsonb, 1, 'SSE: one token at a time, like a dramatic reveal.'),
  ('api-006', 'starter', true, 'llm-apis', 2, 'Roughly how many tokens is 1,000 words of English?', '["About 100","About 1,300","About 10,000","Exactly 1,000"]'::jsonb, 1, 'A token is roughly three quarters of a word. It varies by tokenizer.'),
  ('api-007', 'starter', true, 'llm-apis', 1, 'Lowering the temperature generally makes output…', '["More creative","Run cooler on the GPU","More focused and predictable","Arrive in Celsius"]'::jsonb, 2, 'Low temperature for code, higher for brainstorming band names.'),
  ('api-008', 'starter', true, 'llm-apis', 2, 'What does prompt caching save you?', '["Your prompts, on a USB stick","Reprocessing a repeated prompt prefix: lower cost and latency","The model''s feelings","Nothing, it is a myth"]'::jsonb, 1, 'Put the long, stable stuff first and cache it.'),
  ('api-009', 'starter', true, 'llm-apis', 2, 'How do you return a tool''s output to Claude?', '["Email it","A tool_result block with the matching tool_use_id","Paste it into the system prompt","print() it harder"]'::jsonb, 1, 'IDs matter. Mismatched IDs are how you get 400s.'),
  ('api-010', 'starter', true, 'llm-apis', 2, 'Where does the system prompt go in Anthropic''s Messages API?', '["A message with role \"system\"","The top-level `system` parameter","The HTTP Referer header","A code comment"]'::jsonb, 1, 'Messages are user and assistant only. System gets its own field.'),
  ('api-011', 'starter', true, 'llm-apis', 3, 'Anthropic''s API answers with HTTP 529. What happened?', '["You won a prize","The API is temporarily overloaded: back off and retry","Your key was revoked","Your JSON is haunted"]'::jsonb, 1, '529 overloaded: retry with exponential backoff and a deep breath.'),
  ('api-012', 'starter', true, 'llm-apis', 1, 'What is an embedding?', '["A tiny model inside your HTML","A list of numbers that represents what a text means","A paid ad in the reply","A journalist living in your repo"]'::jsonb, 1, 'Similar meanings, nearby vectors. Math is beautiful.'),
  ('api-013', 'starter', true, 'llm-apis', 2, 'Cosine similarity measures…', '["How aligned two vectors point","How many tokens two texts share","The angle of your monitor","Your trigonometry anxiety"]'::jsonb, 0, '1 means same direction. 0 means unrelated. Your exes are around -1.'),
  ('api-014', 'starter', true, 'llm-apis', 1, 'Exponential backoff means…', '["Retrying instantly, forever","Waiting longer after each failed retry","Backing away from your laptop","Growing your codebase exponentially"]'::jsonb, 1, 'Add jitter so your retries do not stampede.'),
  ('api-015', 'starter', true, 'llm-apis', 2, 'What is an idempotency key for?', '["Unlocking the idempotency room","Making a retried request safe from running twice","Encrypting the payload","Choosing the idempotent model"]'::jsonb, 1, 'Charge the customer once, even if the network hiccups three times.'),
  ('api-016', 'starter', true, 'llm-apis', 1, 'A model''s context window is…', '["A browser pop-up","How many tokens it can consider at once","A window you stare out of while it thinks","Your IDE''s sidebar"]'::jsonb, 1, 'Big windows, but the view still costs tokens.'),
  ('api-017', 'starter', true, 'llm-apis', 2, 'A batch API is the right pick when…', '["You need the answer in 50 ms","You have lots of non-urgent requests and want them cheaper","You want to bake cookies","Your requests are lonely"]'::jsonb, 1, 'Batch it, go to lunch, come back to results.'),
  ('api-018', 'starter', true, 'llm-apis', 2, 'In a tool definition, the JSON Schema describes…', '["The tool''s input parameters","The model''s mood","Your database","The HTTP response time"]'::jsonb, 0, 'Clear schemas, fewer creative interpretations.'),
  ('pr-001', 'starter', true, 'prompting', 1, 'Few-shot prompting means…', '["Prompting after a few drinks","Including a few input→output examples in the prompt","Asking for few-word answers","Rerunning until you get lucky"]'::jsonb, 1, 'Show, don’t tell. Works on models and on junior devs.'),
  ('pr-002', 'starter', true, 'prompting', 1, 'An LLM "hallucination" is…', '["A confident answer that is not grounded in fact","A GPU overheating","A model seeing ghosts in your codebase","A feature request"]'::jsonb, 0, 'Confidence is not correctness. Ask for sources.'),
  ('pr-003', 'starter', true, 'prompting', 1, 'RAG stands for…', '["Really Awesome GPU","Random Answer Generator","Retrieval-Augmented Generation","Rewrite All Git"]'::jsonb, 2, 'Fetch the right documents first, then generate.'),
  ('pr-004', 'starter', true, 'prompting', 1, 'Chain-of-thought prompting asks the model to…', '["Write a blockchain","Reason step by step before answering","Think about chains","Forward the prompt to five friends"]'::jsonb, 1, 'Showing the work helps on multi-step problems.'),
  ('pr-005', 'starter', true, 'prompting', 2, 'The most reliable way to get parseable output is to…', '["Ask nicely, in ALL CAPS","Specify an exact format or schema, then validate it","Add \"pls\" ten times","Hope"]'::jsonb, 1, 'Trust, but JSON.parse in a try block.'),
  ('pr-006', 'starter', true, 'prompting', 2, 'In AI engineering, an "eval" is…', '["JavaScript eval() for prompts","A test suite that scores a model or prompt on known cases","An evil val","Your GPU performance review"]'::jsonb, 1, 'No evals, no idea if your prompt change helped.'),
  ('pr-007', 'starter', true, 'prompting', 1, 'Why put "You are a senior SRE" in a system prompt?', '["To get a raise","It sets the context, tone and expertise of the replies","To unlock the SRE model","Model HR requires it"]'::jsonb, 1, 'Roles focus the model. Titles do not come with equity.'),
  ('pr-008', 'starter', true, 'prompting', 2, 'Why wrap parts of a prompt in XML tags like <document>?', '["Because it is 2003 again","To clearly separate instructions from data","Models only read XML","For SEO"]'::jsonb, 1, 'Clean boundaries, fewer mix-ups.'),
  ('pr-009', 'starter', true, 'prompting', 2, 'Prompt injection is…', '["Injecting caffeine into prompts","Untrusted content carrying instructions that try to hijack the model","A faster way to type prompts","An npm package"]'::jsonb, 1, '"Ignore previous instructions" is the oldest trick in the new book.'),
  ('pr-010', 'starter', true, 'prompting', 2, 'Main benefit of splitting a big task into a chain of smaller prompts?', '["More API calls, more fun","Each step is simpler to get right and to debug","It confuses the model on purpose","Chains look cool in diagrams"]'::jsonb, 1, 'Small steps, small bugs.'),
  ('pr-011', 'starter', true, 'prompting', 2, 'Fine-tuning a model means…', '["Adjusting the volume","Training its weights further on your own examples","Writing a nicer prompt","Tuning your guitar during standup"]'::jsonb, 1, 'Try prompting and RAG first. Fine-tune when they top out.'),
  ('pr-012', 'starter', true, 'prompting', 3, 'LoRA, in model training, stands for…', '["Long Range Antenna","Low-Rank Adaptation","Lots of Random Arrays","Logic or Regret Analysis"]'::jsonb, 1, 'Train small adapter matrices instead of every weight. Cheap and cheerful.'),
  ('pr-013', 'starter', true, 'prompting', 2, 'RLHF stands for…', '["Really Long Hello Function","Reinforcement Learning from Human Feedback","Rate Limit Handling Framework","Run Locally, Hope Fervently"]'::jsonb, 1, 'Humans rate the answers, the model learns what helps.'),
  ('pr-014', 'starter', true, 'prompting', 2, 'The 2017 paper "Attention Is All You Need" introduced…', '["The Transformer","The GPU","Standup meetings","Infinite scroll"]'::jsonb, 0, 'Also true of toddlers and production incidents.'),
  ('pr-015', 'starter', true, 'prompting', 1, 'GPT stands for…', '["General Purpose Terminal","Generative Pre-trained Transformer","Got Prompts Today?","Giant Python Thing"]'::jsonb, 1, 'Generative, pre-trained, transformer. Three words, one industry.'),
  ('pr-016', 'starter', true, 'prompting', 3, '"Constitutional AI" trains a model using…', '["A written set of principles to critique and improve its answers","The US Constitution only","Daily walks","Votes from a model parliament"]'::jsonb, 0, 'An approach Anthropic published: principles in writing.'),
  ('pr-017', 'starter', true, 'prompting', 2, 'Which instruction style tends to work better?', '["Only saying what NOT to do","Saying clearly what TO do","Riddles","Passive-aggressive comments"]'::jsonb, 1, '"Write in plain prose" beats "do not use markdown".'),
  ('ag-001', 'starter', true, 'agents-mcp', 1, 'In practice, an AI "agent" is…', '["A model using tools in a loop to reach a goal","A secret agent with a laptop","A chatbot with sunglasses","Any script with an if-statement"]'::jsonb, 0, 'Think, act, observe, repeat.'),
  ('ag-002', 'starter', true, 'agents-mcp', 1, 'MCP stands for…', '["Master Control Program","Multi-Cloud Pipeline","Model Context Protocol","Mostly Correct Predictions"]'::jsonb, 2, 'A USB-C port for AI apps, as the saying goes.'),
  ('ag-003', 'starter', true, 'agents-mcp', 1, 'MCP lets you…', '["Connect AI apps to tools and data through one standard protocol","Mine crypto with prompts","Compress models","Skip code review"]'::jsonb, 0, 'Write the integration once, use it from any MCP client.'),
  ('ag-004', 'starter', true, 'agents-mcp', 3, 'MCP messages are encoded as…', '["XML-SOAP","JSON-RPC 2.0","Morse code","Protobuf over carrier pigeon"]'::jsonb, 1, 'JSON-RPC: old, boring, works. The best kind of protocol.'),
  ('ag-005', 'starter', true, 'agents-mcp', 2, 'MCP servers'' three core primitives are…', '["Spells, potions and scrolls","Models, views and controllers","Tools, resources and prompts","Bugs, features and excuses"]'::jsonb, 2, 'Tools act, resources inform, prompts template.'),
  ('ag-006', 'starter', true, 'agents-mcp', 2, 'A local MCP server usually talks to its client over…', '["Bluetooth","stdio","Smoke signals","The clipboard"]'::jsonb, 1, 'stdin in, stdout out. Unix never left.'),
  ('ag-007', 'starter', true, 'agents-mcp', 2, 'Which company introduced the Model Context Protocol?', '["Anthropic","A mysterious Discord server","The W3C in 1998","Clippy"]'::jsonb, 0, 'Open-sourced by Anthropic in late 2024.'),
  ('ag-008', 'starter', true, 'agents-mcp', 1, 'Why sandbox an agent that runs shell commands?', '["Agents love sand","To limit the damage from mistakes or injected instructions","It makes them faster","Compliance said so, and nobody knows why"]'::jsonb, 1, '`rm -rf` hits different in a container.'),
  ('ag-009', 'starter', true, 'agents-mcp', 1, '"Human in the loop" means…', '["A person reviews or approves key actions","A developer stuck in a while(true)","Hiring more interns","A rollercoaster"]'::jsonb, 0, 'You. Approving that `git push --force`. Carefully.'),
  ('ag-010', 'starter', true, 'agents-mcp', 2, 'In the orchestrator-worker pattern…', '["A lead agent splits the work, workers do it, the lead combines results","Workers unionize","One agent does everything, slowly","The orchestra plays while you code"]'::jsonb, 0, 'Fan out, fan in.'),
  ('ag-011', 'starter', true, 'agents-mcp', 2, 'Why do tool names and descriptions matter so much?', '["The model decides when and how to call a tool from them","They are shown on billboards","Longer names run faster","They do not matter at all"]'::jsonb, 0, 'A tool called `doStuff` gets called for… stuff.'),
  ('ag-012', 'starter', true, 'agents-mcp', 1, 'A webhook is…', '["A service calling your URL when an event happens","A fishing hook for spiders","Polling every second, forever","A browser extension"]'::jsonb, 0, 'Don''t call us, we''ll call you.'),
  ('ag-013', 'starter', true, 'agents-mcp', 2, 'Why compact or summarize a long agent session?', '["Long contexts cost more and can blur the focus","Agents get bored","Summaries are legally required","To make the logs rhyme"]'::jsonb, 0, 'Keep the signal, drop the scrollback.'),
  ('dl-001', 'starter', true, 'dev-lore', 1, 'HTTP 418 means…', '["I''m a teapot","Server melted","Unauthorized coffee","Too many teapots"]'::jsonb, 0, 'An April Fools RFC that refuses to die.'),
  ('dl-002', 'starter', true, 'dev-lore', 2, 'What does `git bisect` do?', '["Splits your repo in two","Binary-searches commits for the one that broke things","Cuts a branch diagonally","Blames your cat"]'::jsonb, 1, 'log₂(n) steps to find the culprit. It was you. It is always you.'),
  ('dl-003', 'starter', true, 'dev-lore', 1, 'Rubber duck debugging is…', '["Debugging in the bathtub","Explaining your code line by line until the bug reveals itself","A duck-typed language feature","Hiring a duck"]'::jsonb, 1, 'Claude is a very chatty duck.'),
  ('dl-004', 'starter', true, 'dev-lore', 2, 'You lost commits after a bad `git reset --hard`. What saves you?', '["git reflog","git pray","Ctrl+Z","A new laptop"]'::jsonb, 0, 'The reflog remembers what you wish you could forget.'),
  ('dl-005', 'starter', true, 'dev-lore', 1, 'An off-by-one error is…', '["A loop that runs one time too many or too few","Being one coffee short","A typo in your name","A bug in one file only"]'::jsonb, 0, 'There are two hard things in CS… and off-by-one errors.'),
  ('dl-006', 'starter', true, 'dev-lore', 1, 'What does `git stash` do?', '["Hides your snacks","Shelves uncommitted changes to reapply later","Deletes the branch","Pushes to production"]'::jsonb, 1, 'stash@{37} is where good intentions go to wait.'),
  ('dl-007', 'starter', true, 'dev-lore', 2, '"Yak shaving" is…', '["A chain of side quests you must finish before the real task","A grooming plugin","A Linux distro","Refactoring with scissors"]'::jsonb, 0, 'You came to fix a typo. You are now upgrading the build system.'),
  ('dl-008', 'starter', true, 'dev-lore', 1, 'Stripe''s classic test card number is…', '["1234 5678 9012 3456","4242 4242 4242 4242","0000 0000 0000 0000","6969 6969 6969 6969"]'::jsonb, 1, 'The most-typed card number in history. Never charged a cent.'),
  ('dl-009', 'starter', true, 'dev-lore', 2, 'Stripe expresses an amount like $10.00 as…', '["10","10.00","1000 (the smallest unit: cents)","\"ten bucks\""]'::jsonb, 2, 'Integers for money. Floats for regret.'),
  ('dl-010', 'starter', true, 'dev-lore', 1, 'Supabase is built on top of…', '["PostgreSQL","Excel","A very large JSON file","MongoDB"]'::jsonb, 0, 'Postgres: still the answer, whatever the question was.'),
  ('dl-011', 'starter', true, 'dev-lore', 2, 'pgvector is…', '["A Postgres extension for vector similarity search","A graphics card","A vector font for pgAdmin","A pager for DBAs"]'::jsonb, 0, 'Embeddings next to your data. RAG without another database.'),
  ('dl-012', 'starter', true, 'dev-lore', 2, 'Row Level Security (RLS) in Postgres is…', '["Policies that decide which rows each user can see or change","Locking the server room","Encrypting every row twice","A rowing club for DBAs"]'::jsonb, 0, 'Enable it before you ship your anon key. Please.'),
  ('dl-013', 'starter', true, 'dev-lore', 1, 'Time complexity of binary search?', '["O(n²)","O(log n)","O(n!)","O(no)"]'::jsonb, 1, 'Halve it, halve it again. Like your sprint scope.'),
  ('dl-014', 'starter', true, 'dev-lore', 1, 'With semantic versioning, a breaking change bumps the…', '["PATCH","MINOR","MAJOR","Mood"]'::jsonb, 2, 'MAJOR.MINOR.PATCH. Or, as some ship it, YOLO.YOLO.YOLO.'),
  ('dl-015', 'starter', true, 'dev-lore', 1, 'A "Heisenbug" is a bug that…', '["Only appears in chemistry labs","Changes or vanishes when you try to observe it","Was written by a physicist","Lives in the cache"]'::jsonb, 1, 'Add a print statement and it is gone. Remove it and it is back.'),
  ('dl-016', 'starter', true, 'dev-lore', 2, '`sudo` originally stood for…', '["superuser do","Shut Up and Do Over","super undo","Seriously, Use Docker Only"]'::jsonb, 0, 'With great power comes great `sudo !!`.'),
  ('dl-017', 'starter', true, 'dev-lore', 2, 'The C in the CAP theorem is…', '["Caching","Consistency","Coffee","Containers"]'::jsonb, 1, 'Consistency, Availability, Partition tolerance: pick two when the network splits.'),
  ('dl-018', 'starter', true, 'dev-lore', 1, '"It works on my machine." The modern fix?', '["Ship your machine","Containers, so every machine is your machine","Stop testing","Blame DNS"]'::jsonb, 1, 'Then again, it is always DNS.'),
  ('dl-019', 'starter', true, 'dev-lore', 1, 'Which HTTP status means "Not Found"?', '["200","301","404","500"]'::jsonb, 2, 'Like my motivation on Monday mornings.'),
  ('dl-020', 'starter', true, 'dev-lore', 2, 'What is a race condition?', '["A bug that depends on the timing of concurrent operations","A CPU that overclocks itself","Two devs racing to merge first","A Formula 1 sponsorship clause"]'::jsonb, 0, 'Works 99 times, fails on the 100th, during the demo.')
